CREATE TABLE onsite.events(id uuid PRIMARY KEY,tenant_id uuid NOT NULL,source_event_id text NOT NULL,name text NOT NULL,status text NOT NULL CHECK(status IN ('draft','active','closed')),starts_at timestamptz NOT NULL,ends_at timestamptz NOT NULL,UNIQUE(tenant_id,source_event_id));
CREATE TABLE onsite.scopes(id uuid PRIMARY KEY,event_id uuid NOT NULL REFERENCES onsite.events(id),code text NOT NULL,name text NOT NULL,kind text NOT NULL CHECK(kind IN ('event','venue','gate','session','track')),UNIQUE(event_id,code));
CREATE TABLE onsite.devices(id uuid PRIMARY KEY,tenant_id uuid NOT NULL,label text NOT NULL,status text NOT NULL CHECK(status IN ('active','revoked')),revoked_at timestamptz);
CREATE TABLE onsite.operator_assignments(id uuid PRIMARY KEY,user_id uuid NOT NULL,event_id uuid NOT NULL REFERENCES onsite.events(id),scope_id uuid NOT NULL REFERENCES onsite.scopes(id),device_id uuid NOT NULL REFERENCES onsite.devices(id),role text NOT NULL CHECK(role IN ('staff','supervisor','manager')),valid_from timestamptz NOT NULL,valid_until timestamptz);
